const D = (function(){
// Elaborado por: Jorge Valencia. Reglas de decision V2; sin red ni LLM.
function canonical(x) {
  if (Array.isArray(x)) return x.map(canonical);
  if (x && typeof x === 'object') return Object.fromEntries(Object.keys(x).sort().map(k => [k,canonical(x[k])]));
  return x === undefined ? null : x;
}
function snapshot(c, reglas, fuentes) {
  const keys=['empleado_id','fecha_inicio','fecha_fin','equipo_id','periodo_inicio','periodo_fin','dias_solicitados','dias_laborables','reservas_aprobadas','saldo_actual','saldo_proyectado','saldo_suficiente','plazo_limite','plazo_ok','plantilla_equipo','cobertura_minima','cobertura_detalle','dias_conflicto','cobertura_ok','tasa_prima','salario_diario_mxn','prima_bruta_mxn','prima_cubierta_mxn','prima_adicional_mxn','prima_revision_manual'];
  const r={version_reglas:reglas||'',version_fuentes:fuentes||''};
  keys.forEach(k=>r[k]=c[k]===undefined?null:c[k]);
  return JSON.stringify(canonical(r));
}
function metadata(c, version, now, minutes) {
  if (!Number.isInteger(version)||version<1) return null;
  return {version,emitida_en:new Date(now).toISOString(),vence_en:new Date(now+minutes*60000).toISOString(),snapshot:snapshot(c,c.version_reglas,c.version_fuentes),autor:'Jorge Valencia'};
}
function parseDecision(text) {
  const p=String(text).trim().split(/\s+/); const cmd=(p[0]||'').split('@')[0].toLowerCase();
  if (cmd==='/probar_control'&&p.length===1) return {tipo:'probar_control'};
  if(!['/aprobar','/rechazar'].includes(cmd))return null;
  if(!/^VAC-[A-Z0-9-]{4,80}$/i.test(p[1]||'')||!/^V[1-9][0-9]{0,2}$/i.test(p[2]||''))return {error:'Usa /aprobar FOLIO V1 o /rechazar FOLIO V1 motivo.'};
  const motivo=p.slice(3).join(' ');
  if(cmd==='/aprobar'&&p.length!==3)return {error:'La aprobación requiere solo folio y versión. No incluyas instrucciones adicionales.'};
  if(cmd==='/rechazar'&&(motivo.length<5||motivo.length>300))return {error:'El motivo de rechazo debe tener entre 5 y 300 caracteres.'};
  return {tipo:cmd.slice(1),folio:p[1].toUpperCase(),version:Number(p[2].slice(1)),motivo:cmd==='/rechazar'?motivo:''};
}
function plan(caseRow, req, event, now) {
  const no=msg=>({accion:'ninguna',mensaje:msg});
  if(!caseRow)return no('No existe un caso asociado a tu usuario y chat con ese folio.');
  if(String(caseRow.usuario_id)!==String(event.usuario_id)||String(caseRow.chat_id)!==String(event.chat_id))return no('No existe un caso asociado a tu usuario y chat con ese folio.');
  if(Number(caseRow.version_propuesta)!==req.version)return no('La versión indicada no es la vigente. Consulta /estado FOLIO y utiliza la versión mostrada.');
  if(['Aprobada','Rechazada','Expirada'].includes(caseRow.estado))return no('Este caso ya está '+caseRow.estado.toLowerCase()+'. No se modificaron reservas ni saldos.');
  if(caseRow.estado==='Procesando aprobación')return no('El caso tiene una decisión interrumpida. RH debe revisar la reserva y recuperar el control antes de continuar.');
  let proposal;try{proposal=JSON.parse(caseRow.propuesta_json);}catch(e){return no('La propuesta guardada no tiene un formato válido. Requiere revisión.');}
  const m=proposal.control_decision;
  if(!m||m.version!==req.version||typeof m.snapshot!=='string'||!Number.isFinite(Date.parse(m.vence_en)))return no('Esta propuesta fue creada antes de la V2 o carece de vigencia verificable. Genera una solicitud nueva.');
  if(now>=Date.parse(m.vence_en))return {accion:'expirar',estado:'Expirada',proposal,mensaje:'La propuesta venció. No se reservaron días. Genera una solicitud nueva.'};
  const decidibles=['Pendiente de aprobación','Requiere ajuste por cobertura','Saldo insuficiente','Requiere aclaración'];
  if(!decidibles.includes(caseRow.estado))return no('El estado actual no permite registrar una decisión.');
  if(req.tipo==='rechazar')return {accion:'rechazar',estado:'Rechazada',proposal,mensaje:'Solicitud rechazada. Motivo: '+req.motivo+'. No se reservaron días.'};
  if(caseRow.estado!=='Pendiente de aprobación'||!proposal.revision||proposal.revision.validado!==true||!Array.isArray(proposal.revision.correcciones)||proposal.revision.correcciones.length!==0)return no('Solo se puede aprobar una propuesta viable con revisión validada. Esta solicitud requiere ajuste.');
  return {accion:'revalidar',proposal};
}
function revalidate(plan, state, now) {
  if(now>=Date.parse(plan.proposal.control_decision.vence_en))return {accion:'expirar',estado:'Expirada',proposal:plan.proposal,mensaje:'La propuesta venció durante la revisión. No se reservaron días.'};
  const c=state.calc||{};
  if(!state.apta_especialistas||state.estado_forzado||(state.derivar_rh||[]).length||c.saldo_suficiente!==true||c.cobertura_ok!==true||c.plazo_ok!==true||c.prima_revision_manual){
    return {accion:'actualizar',estado:'Requiere actualización',proposal:plan.proposal,mensaje:'La revisión actual detectó datos, saldo, cobertura o vigencia que impiden aprobar. Genera una nueva propuesta.'};
  }
  if(snapshot(c,c.version_reglas,c.version_fuentes)!==plan.proposal.control_decision.snapshot)return {accion:'actualizar',estado:'Requiere actualización',proposal:plan.proposal,mensaje:'Los datos cambiaron desde que se generó la propuesta. Genera otra solicitud para revisar la nueva situación.'};
  return {accion:'aprobar',estado:'Procesando aprobación',proposal:plan.proposal,calculos:c,mensaje:'Aprobación en proceso.'};
}
function decisionProposal(p,req,event,now,final,approvalId) {
  const copy=JSON.parse(JSON.stringify(p));
  copy.estado=final;
  copy.decision={tipo:req.tipo,version:req.version,usuario_id:String(event.usuario_id),evento_id:event.evento_id,fecha:new Date(now).toISOString(),motivo:req.motivo||'',aprobacion_id:approvalId||null,modo:'SIMULADO'};
  return JSON.stringify(copy);
}
function escaped(t){return String(t).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
return {canonical,snapshot,metadata,parseDecision,plan,revalidate,decisionProposal,escaped};

})();
const t = $('Telegram Trigger').first().json;
const c = $('Configuración').first().json;
const LF = String.fromCharCode(10);
const msg = t.message || {};
const toStr = (v) => (v === undefined || v === null) ? '' : String(v);
const num = (v) => { if (v === '' || v === null || v === undefined) return null; const n = Number(String(v).replace(',', '.')); return Number.isFinite(n) ? n : null; };
const lista = (v) => { if (Array.isArray(v)) return v.map(toStr).map(s => s.trim()).filter(Boolean); if (typeof v === 'string' && v.trim()) return v.split(',').map(s => s.trim()).filter(Boolean); return []; };
const esc = (x) => String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const config = {
  vigencia_aprobacion_min: num(c.VIGENCIA_APROBACION_MIN),
  user_ids: lista(c.USER_IDS_AUTORIZADOS),
  chat_ids: lista(c.CHAT_IDS_AUTORIZADOS),
  modelo: toStr(c.MODELO).trim(),
  max_output_tokens: num(c.MAX_OUTPUT_TOKENS),
  max_llamadas: num(c.MAX_LLAMADAS),
  timeout_ms: num(c.TIMEOUT_MS),
  tope_usd_caso: num(c.TOPE_USD_CASO),
  tarifa_entrada: num(c.TARIFA_ENTRADA_USD_POR_MILLON),
  tarifa_salida: num(c.TARIFA_SALIDA_USD_POR_MILLON),
  tarifa_cache: num(c.TARIFA_CACHE_USD_POR_MILLON),
  cargo_busqueda_usd: num(c.CARGO_BUSQUEDA_USD),
  modo: toStr(c.MODO).trim().toUpperCase(),
  modalidad: toStr(c.MODALIDAD).trim().toLowerCase(),
  reasoning_effort: toStr(c.REASONING_EFFORT).trim().toLowerCase(),
  reasoning_effort_lft: toStr(c.REASONING_EFFORT_LFT).trim().toLowerCase(),
  moneda: toStr(c.MONEDA).trim().toUpperCase(),
  fecha_tarifa: toStr(c.FECHA_TARIFA).trim(),
  url_tarifa: toStr(c.URL_TARIFA).trim(),
  url_modelo: toStr(c.URL_MODELO).trim(),
  url_retiro: toStr(c.URL_RETIRO).trim(),
  retiro_modelo: toStr(c.RETIRO_MODELO_ANUNCIADO).trim(),
  max_tool_calls_lft: num(c.MAX_TOOL_CALLS_LFT),
  supuesto_tokens_contenido_busqueda: num(c.SUPUESTO_TOKENS_CONTENIDO_BUSQUEDA),
  timeout_conteo_ms: num(c.TIMEOUT_CONTEO_MS),
  dominios_lft: ['diputados.gob.mx', 'dof.gob.mx', 'gob.mx']
};
config.version_tarifas = 'openai-' + config.modelo + '-standard-' + config.fecha_tarifa;
const pend = [];
if (config.modelo !== 'gpt-5') pend.push('MODELO (solo se admite exactamente gpt-5; sin gpt-5-chat-latest ni sustitutos)');
if (!(config.max_output_tokens > 0)) pend.push('MAX_OUTPUT_TOKENS');
if (!(config.max_llamadas > 0)) pend.push('MAX_LLAMADAS');
if (!(config.timeout_ms > 0)) pend.push('TIMEOUT_MS');
if (!(config.tope_usd_caso > 0)) pend.push('TOPE_USD_CASO (vacío no significa ilimitado)');
if (!(config.tarifa_entrada > 0)) pend.push('TARIFA_ENTRADA_USD_POR_MILLON');
if (!(config.tarifa_salida > 0)) pend.push('TARIFA_SALIDA_USD_POR_MILLON');
if (config.tarifa_cache === null || !(config.tarifa_cache >= 0)) pend.push('TARIFA_CACHE_USD_POR_MILLON');
if (config.modalidad !== 'standard') pend.push('MODALIDAD (solo standard; sin Batch, Flex ni Priority)');
if (config.reasoning_effort !== 'minimal') pend.push('REASONING_EFFORT (especialistas: minimal)');
if (config.moneda !== 'USD') pend.push('MONEDA (USD)');
if (!/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(config.fecha_tarifa)) pend.push('FECHA_TARIFA');
if (!(config.timeout_conteo_ms > 0)) pend.push('TIMEOUT_CONTEO_MS');
if (config.modo !== 'SIMULADO') pend.push('MODO (V1 solo admite SIMULADO)');
const hoyIso = new Date().toISOString().slice(0, 10);
if (/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(config.retiro_modelo) && hoyIso >= config.retiro_modelo) pend.push('gpt-5 alcanzó su retiro anunciado (' + config.retiro_modelo + '); no hay sustitución automática de modelo');
config.pendientes_llm = pend;
config.llm_habilitado = pend.length === 0;

const evento = {
  update_id: toStr(t.update_id),
  message_id: toStr(msg.message_id),
  chat_id: toStr(msg.chat && msg.chat.id),
  usuario_id: toStr(msg.from && msg.from.id),
  canal: 'telegram',
  fecha_evento: msg.date ? new Date(Number(msg.date) * 1000).toISOString() : ''
};
evento.evento_id = 'tg-' + evento.update_id + '-' + evento.message_id;

const crudo = typeof msg.text === 'string' ? msg.text : '';
const texto_truncado = crudo.length > 1000;
const texto = crudo.slice(0, 1000);
const accesoVerificado = $('Acceso: resolver').first().json;
const acceso = accesoVerificado.usuario_id===evento.usuario_id && accesoVerificado.chat_id===evento.chat_id ? accesoVerificado.access : {autorizado:false,handled:true,mensaje:'No se pudo verificar el acceso.'};
const propietario = config.user_ids.length > 0 && config.chat_ids.length > 0 && config.user_ids.includes(evento.usuario_id) && config.chat_ids.includes(evento.chat_id);
const autorizado = propietario || acceso.autorizado===true;

const AYUDA = [
  'RH Vacaciones BYD (datos ficticios, operación simulada).',
  'Acceso compartido: los usuarios autorizados pueden consultar y decidir sobre los casos ficticios de los tres equipos.',
  'Comandos:',
  '/acceso CODIGO  habilita acceso de prueba con un pase privado.',
  '/probar_control  verifica el control de decisiones sin usar IA.',
  '/aprobar FOLIO V1  aprueba una propuesta vigente.',
  '/rechazar FOLIO V1 motivo  rechaza con motivo.',
  '/nuevo EMP-001 2026-11-23 2026-11-27  inicia una solicitud (empleado, fecha inicio, fecha fin).',
  '/estado FOLIO  consulta el estado y resumen de cualquier caso ficticio compartido.',
  '/lft 80  consulta general sobre un artículo de la Ley Federal del Trabajo.',
  '/ayuda  muestra este mensaje.',
  'Resultado simulado: una propuesta no equivale a una aprobación.'
].join(LF);

let comando = 'respuesta_directa';
let respuesta = '';
let args = {};
const RE_FECHA = /^[0-9]{4}-[0-9]{2}-[0-9]{2}$/;
if (acceso.handled) {
  respuesta = acceso.mensaje;
} else if (!autorizado) {
  respuesta = 'Acceso denegado. Este usuario o chat no está autorizado para el asistente de RH.';
} else if (!texto.trim()) {
  respuesta = 'Envía una solicitud escrita. Escribe /ayuda para ver el formato.';
} else {
  const partes = texto.trim().split(/\s+/);
  const cmd = partes[0].toLowerCase().split('@')[0];
  if (cmd === '/ayuda' || cmd === '/start') {
    respuesta = AYUDA;
  } else if (cmd === '/nuevo') {
    const emp = (partes[1] || '').toUpperCase();
    const fi = partes[2] || '';
    const ff = partes[3] || '';
    if (partes.length === 4 && /^EMP-[0-9]{3,6}$/.test(emp) && RE_FECHA.test(fi) && RE_FECHA.test(ff)) {
      comando = 'nuevo';
      args = { empleado_id: emp, fecha_inicio: fi, fecha_fin: ff };
    } else {
      respuesta = 'Formato no válido. Usa: /nuevo EMP-001 2026-11-23 2026-11-27 (empleado, inicio, fin). No se registró ningún caso.';
    }
  } else if (cmd === '/estado') {
    const folio = (partes[1] || '').toUpperCase();
    if (partes.length === 2 && /^VAC-[A-Z0-9-]{4,60}$/.test(folio)) {
      comando = 'estado';
      args = { folio: folio };
    } else {
      respuesta = 'Formato no válido. Usa: /estado FOLIO (el folio VAC-... que recibiste).';
    }
  } else if (cmd === '/lft') {
    const consulta = partes.slice(1).join(' ').trim();
    if (consulta) { comando = 'lft'; args = { consulta_original: consulta }; }
    else respuesta = 'Indica el artículo o la duda general. Ejemplo: /lft 80';
  } else {
    respuesta = 'No reconozco el mensaje. No se inventan empleados ni fechas.' + LF + AYUDA;
  }
}
if (autorizado && !acceso.handled) {
  const dec = D.parseDecision(crudo);
  if (dec) {
    if (dec.error) { comando='respuesta_directa'; respuesta=dec.error; }
    else { comando='decision'; args=dec; respuesta=''; }
  }
}
return [{ json: { evento, config, acceso_casos: {compartido: autorizado && !acceso.handled, propietario, usuario_id: evento.usuario_id, chat_id: evento.chat_id, vence_en: acceso.vence_en || null}, texto: acceso.handled ? '[control de acceso]' : texto, texto_truncado, autorizado, comando, args, respuesta: esc(respuesta) } }];

// Elaborado por: Jorge Valencia. Permisos calculados en n8n; nunca desde el texto del usuario.
const RHShared = (() => {
  function permitido(n, row, folio, now) {
    const a=n && n.acceso_casos;
    if (!n || n.autorizado!==true || n.config?.modo!=='SIMULADO' || !a || a.compartido!==true) return false;
    if (!n.evento?.usuario_id || !n.evento?.chat_id || a.usuario_id!==n.evento.usuario_id || a.chat_id!==n.evento.chat_id) return false;
    if (a.propietario!==true && !(Number.isFinite(Date.parse(a.vence_en)) && now<Date.parse(a.vence_en))) return false;
    if (!row || row.caso_id!==folio || !/^VAC-[A-Z0-9-]{4,60}$/.test(folio) || !/^EMP-(00[1-9]|01[0-5])$/.test(row.empleado_id||'') || !/^EQ-[ABC]$/.test(row.equipo_id||'')) return false;
    try { return JSON.parse(row.propuesta_json).modo==='SIMULADO'; } catch { return false; }
  }
  return {permitido};
})();

const n=$('Normalizar y autorizar').first().json;
const esc=x=>String(x).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const rows=$input.all().map(i=>i.json).filter(r=>r && r.caso_id===n.args.folio);
let texto='No se encontró un caso ficticio disponible para esta consulta o tu acceso ya no está vigente.';
if(rows.length>1) texto='El folio tiene registros duplicados. RH debe revisar la base.';
else if(rows.length===1 && RHShared.permitido(n,rows[0],n.args.folio,Date.now())) {
 const f={...rows[0]}, p=JSON.parse(f.propuesta_json), md=p.control_decision;
 if(f.estado==='Pendiente de aprobación' && md && Date.now()>=Date.parse(md.vence_en)) f.estado='Expirada por vigencia (sin reserva nueva)';
 const extra='Versión: V'+f.version_propuesta+(md?' | Vigencia hasta: '+md.vence_en:' | Propuesta anterior a V2; generar una nueva para decidir.');
 texto=['Folio: '+f.caso_id,'Estado: '+(f.estado||'desconocido'),'Resumen: '+(f.motivo||'sin resumen'),extra,f.estado==='Aprobada'?'Aprobación simulada.':'Resultado simulado. No equivale a una aprobación.'].join(String.fromCharCode(10));
}
return [{json:{chat_id:n.evento.chat_id,texto:esc(texto)}}];

const n = $('Normalizar y autorizar').first().json;
const esc = (x) => String(x).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const cfg = n.config;
const dup = $input.all().some((i) => i.json && i.json.traza_id);
const orig = String(n.args.consulta_original || '');
const q = orig
  .replace(/EMP-[0-9]+/gi, '')
  .replace(/VAC-[A-Z0-9-]+/gi, '')
  .replace(/[^ ]+@[^ ]+/g, '')
  .replace(/[$][ 0-9.,]+/g, '')
  .replace(/[0-9]{5,}/g, '')
  .replace(/\s+/g, ' ')
  .trim()
  .slice(0, 200);
const consulta = /^[0-9]{1,4}( ?bis)?$/i.test(q)
  ? 'Artículo ' + q + ' de la Ley Federal del Trabajo de México: contenido vigente y resumen breve.'
  : 'Ley Federal del Trabajo de México, duda general: ' + q;
const caso_id = 'LFT-' + n.evento.update_id + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
const motivos = [];
if (dup) motivos.push('evento ya procesado');
if (!q) motivos.push('consulta vacía tras retirar datos personales');
cfg.pendientes_llm.forEach((p) => motivos.push(p + ' pendiente'));
if (!(cfg.cargo_busqueda_usd > 0)) motivos.push('CARGO_BUSQUEDA_USD pendiente');
if (['low', 'medium', 'high'].indexOf(cfg.reasoning_effort_lft) < 0) motivos.push('REASONING_EFFORT_LFT debe ser low, medium o high (la búsqueda web no admite gpt-5 con minimal)');
if (!(cfg.max_tool_calls_lft >= 1)) motivos.push('MAX_TOOL_CALLS_LFT pendiente');
if (cfg.supuesto_tokens_contenido_busqueda === null || !(cfg.supuesto_tokens_contenido_busqueda >= 0)) motivos.push('SUPUESTO_TOKENS_CONTENIDO_BUSQUEDA pendiente');
if (cfg.max_llamadas !== null && cfg.max_llamadas < 1) motivos.push('MAX_LLAMADAS no permite llamadas');
const INSTRUCCIONES = 'Eres un asistente de consulta legal general para un proyecto académico con datos ficticios. Usa la herramienta de búsqueda web integrada; solo se permiten diputados.gob.mx, dof.gob.mx o gob.mx. Responde en español, en texto plano, en máximo 100 palabras, con un resumen del artículo o la duda. No escribas URL en el texto: las fuentes se toman de los metadatos de la búsqueda. Si no encuentras o no puedes verificar la información en esos dominios, dilo claramente y no respondas de memoria. No des asesoría legal personalizada ni propongas cambiar reglas internas.';
const body = {
  model: cfg.modelo,
  instructions: INSTRUCCIONES,
  input: consulta,
  tools: [{ type: 'web_search', filters: { allowed_domains: cfg.dominios_lft }, search_context_size: 'low' }],
  tool_choice: 'auto',
  max_tool_calls: cfg.max_tool_calls_lft,
  include: ['web_search_call.action.sources'],
  reasoning: { effort: cfg.reasoning_effort_lft },
  max_output_tokens: cfg.max_output_tokens,
  store: false,
  service_tier: 'default'
};
const inicio = Date.now();
const ejecucion_id = String($execution.id);
const llamada_actual = { llamada_id: caso_id + '-L1', caso_id: caso_id, etapa: 'lft', agente: 'Consulta legal LFT (búsqueda web)', tipo: 'lft', body: body, grupo_costo: 'operacion', reintento: 0, loop_id: null, skill_id: null, version_propuesta: null, ejecucion_principal: ejecucion_id, evento_id: n.evento.evento_id, inicio_ms_caso: inicio, entrada_traza: { consulta: consulta } };
const permitido = motivos.length === 0;
const respuesta = dup
  ? 'Este mensaje ya fue procesado; no se repitió la búsqueda.'
  : 'Consulta /lft bloqueada. Pendiente: ' + motivos.join('; ') + '. No se sustituye la búsqueda por conocimiento del modelo.';
return [{ json: { permitido, caso_id, consulta, evento: n.evento, config: cfg, inicio_ms: inicio, creado_en: new Date().toISOString(), ejecucion_id, llamada_actual, respuesta: esc(respuesta) } }];

// RH-LIB v2 (2026-11-01) — funciones puras compartidas. Sin red, sin secretos.
const RH = (function () {
  const esNum = (v) => typeof v === 'number' && Number.isFinite(v);
  const esEnteroNoNeg = (v) => esNum(v) && v >= 0 && Math.floor(v) === v;
  const esListaTxt = (v) => Array.isArray(v) && v.every((x) => typeof x === 'string');
  const unicos = (a) => Array.from(new Set(a));

  // Lee usage de Responses API sin sustituir ausencias por cero.
  function leerUsage(usage) {
    const r = { tokens_entrada: null, tokens_cache: null, tokens_salida: null, tokens_razonamiento: null, cache_informada: false, razonamiento_informado: false, usage_presente: false, errores: [] };
    if (!usage || typeof usage !== 'object') { r.errores.push('usage ausente'); return r; }
    r.usage_presente = true;
    if (esEnteroNoNeg(usage.input_tokens)) r.tokens_entrada = usage.input_tokens; else r.errores.push('usage.input_tokens ausente o inválido');
    if (esEnteroNoNeg(usage.output_tokens)) r.tokens_salida = usage.output_tokens; else r.errores.push('usage.output_tokens ausente o inválido');
    const det = usage.input_tokens_details;
    if (det && det.cached_tokens !== undefined && det.cached_tokens !== null) {
      if (!esEnteroNoNeg(det.cached_tokens)) r.errores.push('cached_tokens inválido (' + String(det.cached_tokens) + ')');
      else {
        r.tokens_cache = det.cached_tokens; r.cache_informada = true;
        if (r.tokens_entrada !== null && det.cached_tokens > r.tokens_entrada) r.errores.push('Incoherente: cached_tokens (' + det.cached_tokens + ') > input_tokens (' + r.tokens_entrada + ')');
      }
    }
    const od = usage.output_tokens_details;
    if (od && od.reasoning_tokens !== undefined && od.reasoning_tokens !== null) {
      if (!esEnteroNoNeg(od.reasoning_tokens)) r.errores.push('reasoning_tokens inválido');
      else {
        r.tokens_razonamiento = od.reasoning_tokens; r.razonamiento_informado = true;
        if (r.tokens_salida !== null && od.reasoning_tokens > r.tokens_salida) r.errores.push('Incoherente: reasoning_tokens > output_tokens');
      }
    }
    return r;
  }

  // costo_tokens_usd = ((in - cache) * t_in + cache * t_cache + out * t_out) / 1e6
  // El razonamiento ya está dentro de output_tokens: no se suma otra vez.
  function costoTokens(u, t) {
    if (!t || !(t.entrada > 0) || !(t.salida > 0) || !(t.cache >= 0)) return { costo: null, tipo: 'desconocido', motivo: 'Tarifas incompletas: costo no calculado.' };
    if (u.errores.length || u.tokens_entrada === null || u.tokens_salida === null) return { costo: null, tipo: 'desconocido', motivo: 'Consumo desconocido o incoherente: ' + (u.errores.join('; ') || 'usage incompleto') + '. No se presume costo cero.' };
    const cache = u.cache_informada ? u.tokens_cache : 0;
    const costo = ((u.tokens_entrada - cache) * t.entrada + cache * t.cache + u.tokens_salida * t.salida) / 1000000;
    if (u.cache_informada) return { costo: costo, tipo: 'calculado', motivo: 'Tokens medidos por usage de la API; costo calculado con tarifas configuradas. No es factura conciliada.' };
    return { costo: costo, tipo: 'estimado', motivo: 'Caché no informada por la API: estimación conservadora sin descuento de caché (no se afirma caché medida = 0). No es factura conciliada.' };
  }

  // Reserva previa: entrada contada a tarifa normal (sin presumir caché) + salida máxima permitida.
  function reservaLlamada(p) {
    const tokens = (p.tokens_conteo * p.t.entrada + p.max_salida * p.t.salida) / 1000000;
    const herramienta = (p.busquedas_max || 0) * (p.cargo_busqueda || 0);
    const contenido = (p.tokens_contenido_supuesto || 0) * p.t.entrada / 1000000;
    return { tokens: tokens, herramienta: herramienta, contenido: contenido, total: tokens + herramienta + contenido };
  }

  // Estado del presupuesto del caso a partir de las filas originales de rh_costos.
  function estadoPresupuesto(filas) {
    const gen = (filas || []).filter((f) => f && f.tipo_registro === 'generacion');
    let contabilizado = 0; let pendiente = 0; let sinCota = 0;
    gen.forEach((f) => {
      const ec = String(f.estado_conciliacion || '');
      if ((ec === 'calculado' || ec === 'estimado' || ec === 'conciliado') && esNum(f.costo_usd)) contabilizado += f.costo_usd;
      else if (esNum(f.costo_reservado_usd)) pendiente += f.costo_reservado_usd;
      else sinCota += 1;
    });
    return { intentos: gen.length, contabilizado: contabilizado, pendiente: pendiente, sin_cota: sinCota };
  }

  function evaluarAutorizacion(est, reserva, cfg) {
    const motivos = [];
    if (cfg.max_llamadas > 0 && est.intentos + 1 > cfg.max_llamadas) motivos.push('MAX_LLAMADAS alcanzado (' + est.intentos + ' intentos de generación de ' + cfg.max_llamadas + ')');
    if (est.sin_cota > 0) motivos.push(est.sin_cota + ' llamada(s) previa(s) con consumo desconocido y sin reserva cuantificada');
    if (!(cfg.tope_usd_caso > 0)) motivos.push('TOPE_USD_CASO no configurado (vacío no es ilimitado)');
    if (reserva === null) motivos.push('Sin reserva calculable');
    else {
      const total = est.contabilizado + est.pendiente + reserva.total;
      if (total > cfg.tope_usd_caso) motivos.push('Presupuesto insuficiente: contabilizado ' + est.contabilizado + ' + reservas pendientes ' + est.pendiente + ' + nueva reserva ' + reserva.total + ' = ' + total + ' USD > TOPE_USD_CASO ' + cfg.tope_usd_caso);
    }
    return motivos;
  }

  function mensajeErrorApi(status, body, modelo, fase) {
    const e = (body && body.error) || {};
    const msg = String(e.message || (typeof body === 'string' ? body : '') || '').slice(0, 300);
    const code = String(e.code || '');
    if (status === 404 || code === 'model_not_found' || /model/i.test(msg) && /(not exist|not found|does not have access|no access)/i.test(msg)) {
      return 'El modelo ' + modelo + ' no está disponible para la credencial o cuenta (' + fase + ', HTTP ' + status + (code ? ', ' + code : '') + '): ' + msg + '. No se sustituye por otro modelo.';
    }
    return 'Error de API en ' + fase + ' (HTTP ' + status + (code ? ', ' + code : '') + '): ' + msg;
  }

  // Extrae el texto final de una respuesta; solo 'completed' libera contenido.
  function extraerTexto(resp) {
    const r = { status: resp && resp.status ? String(resp.status) : null, texto: null, motivo: '' };
    if (!resp || typeof resp !== 'object') { r.motivo = 'Respuesta vacía'; return r; }
    if (r.status !== 'completed') {
      const det = resp.incomplete_details && resp.incomplete_details.reason ? ' (' + resp.incomplete_details.reason + ')' : '';
      r.motivo = 'Respuesta no completada: status ' + r.status + det;
      return r;
    }
    const msgs = (Array.isArray(resp.output) ? resp.output : []).filter((o) => o && o.type === 'message');
    const partes = [];
    msgs.forEach((m) => (m.content || []).forEach((c) => { if (c && c.type === 'output_text' && typeof c.text === 'string') partes.push(c.text); }));
    if (!partes.length) { r.motivo = 'Sin texto de salida'; return r; }
    r.texto = partes.join('\n');
    return r;
  }

  function hostPermitido(u, permitidos) {
    try { const x = new URL(String(u)); const h = x.hostname.toLowerCase(); return x.protocol === 'https:' && permitidos.some((d) => h === d || h.endsWith('.' + d)); } catch (e) { return false; }
  }
  function normUrl(u) {
    try { const x = new URL(String(u)); return x.hostname.toLowerCase().replace(/^www[.]/, '') + x.pathname.replace(/[/]+$/, ''); } catch (e) { return null; }
  }

  // Evidencia de búsqueda desde los metadatos devueltos (web_search_call y anotaciones), no desde el texto.
  function extraerBusqueda(resp, permitidos) {
    const out = resp && Array.isArray(resp.output) ? resp.output : [];
    const llamadas = out.filter((o) => o && o.type === 'web_search_call');
    const sinAccion = llamadas.filter((c) => !c.action || !c.action.type).length;
    const cobrables = llamadas.filter((c) => !c.action || !c.action.type || c.action.type === 'search').length;
    const completadas = llamadas.filter((c) => c.status === 'completed').length;
    const fuentes = [];
    llamadas.forEach((c) => { const ss = c.action && Array.isArray(c.action.sources) ? c.action.sources : []; ss.forEach((s) => { if (s && s.url) fuentes.push(String(s.url)); }); });
    const anot = [];
    out.filter((o) => o && o.type === 'message').forEach((m) => (m.content || []).forEach((p) => (p.annotations || []).forEach((a) => { if (a && a.type === 'url_citation' && a.url) anot.push({ url: String(a.url), title: String(a.title || '') }); })));
    const setFuentes = new Set(fuentes.map(normUrl).filter(Boolean));
    const recuperadasPermitidas = unicos(fuentes.filter((u) => hostPermitido(u, permitidos)));
    const ajenas = unicos(fuentes.filter((u) => !hostPermitido(u, permitidos)));
    const citasVerificadas = unicos(anot.filter((a) => hostPermitido(a.url, permitidos) && setFuentes.has(normUrl(a.url))).map((a) => a.url));
    const citasNoVerificadas = unicos(anot.map((a) => a.url).filter((u) => citasVerificadas.indexOf(u) < 0));
    const mostrar = citasVerificadas.length ? citasVerificadas : recuperadasPermitidas;
    return {
      llamadas_observadas: llamadas.length,
      busquedas_cobrables: cobrables,
      llamadas_sin_accion: sinAccion,
      llamadas_completadas: completadas,
      ids: llamadas.map((c) => String(c.id || '')),
      fuentes_recuperadas: unicos(fuentes),
      fuentes_permitidas: recuperadasPermitidas,
      fuentes_ajenas: ajenas,
      citas_verificadas: citasVerificadas,
      citas_no_verificadas: citasNoVerificadas,
      mostrar: mostrar,
      verificable: completadas > 0 && recuperadasPermitidas.length > 0
    };
  }

  // validado=true exige correcciones=[]; validado=false exige al menos una corrección concreta.
  function validarRevision(o) {
    const e = [];
    if (!o || typeof o !== 'object') return ['Salida vacía'];
    if (typeof o.validado !== 'boolean') e.push('validado no es booleano');
    if (!esListaTxt(o.correcciones)) e.push('correcciones no es lista de textos');
    if (!esListaTxt(o.observaciones)) e.push('observaciones no es lista de textos');
    if (e.length) return e;
    const concretas = o.correcciones.filter((c) => c.trim().length >= 8);
    if (o.validado === true && o.correcciones.length > 0) e.push('Contradicción: validado=true con correcciones no vacías');
    if (o.validado === false && concretas.length === 0) e.push('Contradicción: validado=false sin una corrección concreta');
    return e;
  }

  // JSON siempre válido; si excede el límite guarda un resumen con indicación de truncamiento.
  function jsonSeguro(v, n) {
    const t = JSON.stringify(v === undefined ? null : v);
    if (t.length <= n) return t;
    const resumen = { truncado: true, longitud_original: t.length, resumen: t.slice(0, Math.max(0, n - 120)) };
    let r = JSON.stringify(resumen);
    while (r.length > n && resumen.resumen.length > 0) { resumen.resumen = resumen.resumen.slice(0, Math.floor(resumen.resumen.length * 0.8)); r = JSON.stringify(resumen); }
    return r;
  }

  function cuerpoConteo(body) {
    const permitidas = ['model', 'instructions', 'input', 'text', 'tools', 'tool_choice', 'reasoning', 'parallel_tool_calls'];
    const c = {};
    permitidas.forEach((k) => { if (body[k] !== undefined) c[k] = body[k]; });
    return c;
  }

  function armarLlamadaEspecialista(s, p) {
    const cfg = s.config;
    const body = {
      model: cfg.modelo,
      instructions: p.instrucciones,
      input: p.prompt,
      text: { format: { type: 'json_schema', name: p.nombre_esquema, schema: p.esquema, strict: true } },
      reasoning: { effort: cfg.reasoning_effort },
