// Corrección de fechas V2.1. Elaborado por: Jorge Valencia.
function fechaNegocio(v){
  if(typeof v!=='string')return null;
  if(/^\d{4}-\d{2}-\d{2}$/.test(v)){
    const x=new Date(v+'T00:00:00Z');
    return Number.isFinite(x.getTime())&&x.toISOString().slice(0,10)===v?v:null;
  }
  if(!/^\d{4}-\d{2}-\d{2}T.*(?:Z|[+-]\d{2}:\d{2})$/i.test(v))return null;
  const x=new Date(v);if(!Number.isFinite(x.getTime()))return null;
  const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:'America/Mexico_City',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(x).map(p=>[p.type,p.value]));
  return p.year+'-'+p.month+'-'+p.day;
}
function compararReserva(rows,f){
  const found=rows.filter(r=>r&&r.aprobacion_id===f.aprobacion_id);
  const errores=[];
  if(found.length!==1)return {ok:false,errores:['Se esperaba una única reserva; se recuperaron '+found.length]};
  const r=found[0];
  for(const k of ['aprobacion_id','empleado_id','equipo_id','estado'])if(typeof r[k]!=='string'||r[k]!==f[k])errores.push(k+' no coincide');
  for(const k of ['fecha_inicio','fecha_fin'])if(!fechaNegocio(r[k])||fechaNegocio(r[k])!==fechaNegocio(f[k]))errores.push(k+' no coincide en America/Mexico_City');
  const q=r.dias_reservados;
  if(q===null||q===''||typeof q==='boolean'||!Number.isInteger(Number(q))||Number(q)<=0||Number(q)!==Number(f.dias_reservados))errores.push('dias_reservados no coincide');
  if(r.error)errores.push('La tabla devolvió un error');
  return {ok:errores.length===0,errores};
}



